package br.com.mikael.nexustech.gui;
import br.com.mikael.nexustech.energy.TileEntityCoalGenerator;import net.minecraft.entity.player.*;import net.minecraft.inventory.*;import net.minecraftforge.items.SlotItemHandler;
public class ContainerCoalGenerator extends Container{private final TileEntityCoalGenerator tile;public ContainerCoalGenerator(InventoryPlayer inv,TileEntityCoalGenerator te){tile=te;addSlotToContainer(new SlotItemHandler(te.getInventory(),0,80,35));for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlotToContainer(new Slot(inv,c+r*9+9,8+c*18,84+r*18));for(int c=0;c<9;c++)addSlotToContainer(new Slot(inv,c,8+c*18,142));}public boolean canInteractWith(EntityPlayer p){return !tile.isInvalid()&&p.getDistanceSq(tile.getPos().getX()+0.5,tile.getPos().getY()+0.5,tile.getPos().getZ()+0.5)<=64.0;}}